// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target, bytes memory data, address caller) public {
        vm.assume(caller != c.owner());
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.deal(address(c), 100 ether);
        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        try c.sendMoney(target, amount, data) { } catch { }
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore);
    }
}
